#!/usr/bin/env python3
"""Read-only extraction of unit-converter tables and bounded code evidence."""
from pathlib import Path
import hashlib, json, struct
from firmware_disassembly import disassemble_arm
ROOT=Path(__file__).resolve().parents[1]
SOURCE=ROOT/'nokia-ta1278-research/firmware/original/system-20261025T054301+0800/user.bin'
INIT=ROOT/'nokia-ta1278-research/analysis/extracted/kernel/init_81c20000.bin'
b=SOURCE.read_bytes(); init=INIT.read_bytes(); sha=lambda x:hashlib.sha256(x).hexdigest()
assert sha(b)=='8f0db2dc82f9e763cb700c2e5781b7ca7125a4d250f4c075dbec793eb549c1ca'
assert sha(init)=='76b95ae0d1948b677a38d8e6311b65f154642fb19723a4dcdcc8ec0a2da04210'
base=0x88000000; table=0x81c47c24
assert struct.unpack_from('<I',b,0xb9d484)[0]==table
strings={int(r['resource_id'],16):r for r in json.loads((ROOT/'nokia-ta1278-research/analysis/ui/strings-zh-Hans-observed.json').read_text())}
# Menu insertion order traced at 88b9d7d0; labels traced at 88b9df6c onward.
ids=[[0x1c,0x1d,0x1e],[0x26,0x22,0x23,0x24,0x25],[0x32,0x2e,0x2f,0x30,0x31],list(range(0x3a,0x3f)),list(range(0x48,0x4c))]
labels=[[(0x1f,0x20),(0x21,0x1f),(0x21,0x20)],[(0x2b,0x2d),(0x27,0x2c),(0x28,0x2c),(0x29,0x2c),(0x2a,0x2d)],[(0x38,0x39),(0x33,0x34),(0x35,0x34),(0x35,0x36),(0x37,0x36)],[(0x3f,0x40),(0x41,0x42),(0x43,0x40),(0x44,0x45),(0x46,0x47)],[(0x4c,0x4d),(0x4e,0x4f),(0x4f,0x50),(0x51,0x52)]]
def text(i): return strings[0x40170000+i]['text']
def literal(off):
 ptr=struct.unpack_from('<I',init,table-0x81c20000+off)[0]
 end=b.index(0,ptr-base);return {'table_offset':hex(off),'address':hex(ptr),'text':b[ptr-base:end].decode('ascii')}
rows=[]; rust=['// Generated by scripts/recover-converter.py from verified system images.','use super::Conversion;','pub const CATEGORIES: &[&str] = &["温度", "重量", "长度", "面积", "体积", "货币"];','pub static PAIRS: &[&[Conversion]] = &[']
for category, group in enumerate(ids):
 rust.append('    &[')
 for index, rid in enumerate(group):
  off=([0x18,0x30,0x58,0x80,0xa8][category])+index*8
  factor=literal(off); offsets=[literal(index*8+i*4) for i in range(2)] if category==0 else []
  row={'category':category,'index':index,'menu_resource':hex(0x40170000+rid),'title':text(rid),'labels':[text(i) for i in labels[category][index]],'factor':factor,'unused_reciprocal':literal(off+4),'offsets':offsets}
  # Native dispatch loads the first factor, divides for reverse, then adds that direction's offset.
  f=factor['text'].split('/');num=float(f[0]);den=float(f[1]) if len(f)==2 else 1.
  adds=[float(v['text']) for v in offsets] if offsets else [0.,0.]
  rust.append('        Conversion { title: '+json.dumps(row['title'],ensure_ascii=False)+', labels: ['+', '.join(json.dumps(s,ensure_ascii=False) for s in row['labels'])+f'], numerator: {num!r}, denominator: {den!r}, offsets: [{adds[0]!r}, {adds[1]!r}] }},')
  rows.append(row)
 rust.append('    ],')
rust.append('];')
(ROOT/'crates/phone-core/src/converter/data.rs').write_text('\n'.join(rust)+'\n')
windows=[r for r in json.loads((ROOT/'nokia-ta1278-research/analysis/ui/window-semantics.json').read_text())['windows'] if 'MMIUNITCONV_' in (r.get('name') or '')]
for r in windows:
 at=int(r['offset'],16);assert sha(b[at:at+r['size']])==r['sha256']
# Runtime validation is stricter than the descriptor's 13-unit capacity.
assert b[0xb9e4de:0xb9e4e2].hex()=='0c2814d9'
ranges=[(0x88b9cf26,0x88b9d31c),(0x88b9d3e8,0x88b9d4bc),(0x88b9d7d0,0x88b9da9a),(0x88b9df52,0x88b9e152),(0x88b9e4d6,0x88b9e634)]
(ROOT/'docs/evidence/converter-thumb.txt').write_text(disassemble_arm(b,base,ranges))
report={'source':str(SOURCE.relative_to(ROOT)),'source_sha256':sha(b),'initialization':str(INIT.relative_to(ROOT)),'initialization_sha256':sha(init),'table_address':hex(table),'table_sha256':sha(init[table-0x81c20000:table-0x81c20000+0xc8]),'pairs':rows,'windows':windows,'runtime_input_limit':12,'descriptor_capacity':13,'ranges':[{'start':hex(a),'end':hex(z),'sha256':sha(b[a-base:z-base])} for a,z in ranges],
'confirmed':['22 pair entries, menu order and conversion factors from ROM and initialized pointers.','Forward computes input*numerator/denominator + forward offset; reverse computes input*denominator/numerator + reverse offset. The adjacent rounded reciprocal strings are not used by this dispatcher.','Native result formatter uses ten decimal places, copies 12 characters for nonnegative or 16 for negative fixed output, then trims trailing zeros; tiny nonzero results take %e.','Runtime rejects input length above 12 despite child descriptor capacity 13.'],
'limits':['Decimal parsing/rounding at halfway values may differ between Rust and the original C library.','Currency and saved custom conversions are not implemented or claimed equivalent.','Physical captures cover temperature only; other pair labels/order and arithmetic are static evidence.','Clear-all, signed input shortcuts and invalid-input feedback use local policies where physical transitions are absent.']}
(ROOT/'docs/evidence/converter-recovery.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
print('Verified converter descriptors, 22 pair entries, runtime limit, coefficient tables and bounded arithmetic code.')
